let heroes={},games=[],selected=0,deep=false,busy=false,account=E.storage.read('account'),teaching=E.storage.read('teaching',false),demo=true;
function sample(){const ids=[50,4,2,1,6,13,15,25,27,10];return Array.from({length:20},(_,i)=>{const duration=1740+(i*131)%1100,pace=610+(i*47)%340,series=Array.from({length:Math.floor(duration/180)},(_,j)=>[(j+1)*180,Math.round(pace*(j+1)*3*(.72+j*.038)+Math.sin(j+i)*320)]);const early=Math.min(3+i%7,1+i%4),deaths=Array.from({length:3+i%7},(_,j)=>j<early?180+j*120:800+(j-early)*110);return{id:900000+i,start:Math.floor(Date.now()/1000)-i*7800-3600,hero:ids[i%ids.length],win:[0,1,4,5,8,11,12,14,17,18,19].includes(i),k:4+i%9,d:3+i%7,a:8+i%13,duration,souls:series.at(-1)[1],ready:true,schema:2,gameMode:1,paceTime:720,lobbyTime:540,damageTime:series.at(-1)[0],pace:series[3][1]/12,lobby:-1400+(i*317)%2600,cs:65+(i*7)%31,earlyDeaths:early,damage:12+(i*3)%16,deaths,series,lead:series.map(([t],j)=>[t,Math.round(Math.sin(j*.55+i)*4200)])};});}
