function renderMatch(){const g=games[selected];$('#overview').classList.toggle('active',!deep);$('#review').classList.toggle('active',deep);$('#overview').setAttribute('aria-pressed',String(!deep));$('#review').setAttribute('aria-pressed',String(deep));if(!g){$('#workspace').innerHTML='<div class="card empty">No matches available yet. Connect an account or explore the demo.</div>';return;}
 const rows=E.compare(g,games),focus=E.focus(g,rows),gap=focus.gap,observations=E.moments(g),others=E.peers(g,games).length,economy=chart(g),otherLabel=`${others} other match${others===1?'':'es'}`;
 const {headline,detail}=focus;
 $('#workspace').innerHTML=`<div class="desk"><article class="card"><div class="match-top">${portrait(g,'portrait')}<div><span class="result ${g.win===null?'unknown':g.win?'':'loss'}">${g.win===null?'RESULT UNAVAILABLE':g.win?'VICTORY':'DEFEAT'} <span style="color:var(--dim)"> / ${demo?'EXAMPLE':new Date(g.start*1000).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span></span><h2>${esc(hero(g).name)}</h2><p>${E.time(g.duration)} match</p></div><div class="match-id">MATCH ${selected+1} OF ${games.length}<br>${demo?'Illustrative data':'#'+g.id}</div></div><div class="scoreline"><div><strong>${g.k} <span>/</span> ${g.d} <span>/</span> ${g.a}</strong><span>${teaching?'Kills / deaths / assists':'K / D / A'}</span></div><div><strong>${E.valid(g.souls)?num(g.souls/1000,1)+'k':'—'}</strong><span>${teaching?'Souls · match currency':'Final Souls'}</span></div><div><strong>${num(kda(g),2)}</strong><span>${teaching?'(Kills + assists) / max(1, deaths)':'KDA ratio'}</span></div></div><div class="chart-head"><h3>Your economy, in context</h3><span class="legend"><b>— This match</b>${economy.hasBaseline?' ╌ Your window':''}</span></div>${economy.markup}<p class="chart-note">${economy.hasBaseline?`Compared with up to ${otherLabel} in the same game mode. The dashed line uses only games still supplying data at each timestamp; later points can have fewer contributors. Heroes and match lengths vary.`:'Only this match is shown because no comparison game has economy data in the same game mode.'}${teaching?' Souls are the currency you earn in a match.':''}</p></article><aside class="card focus"><div class="eyebrow">01 / YOUR NEXT FOCUS</div><h3>${headline}</h3><p>${detail}${teaching&&gap?' '+gap.detail:''}</p><div class="next"><span>${gap?'TRY THIS NEXT GAME':'KEEP IT IN PERSPECTIVE'}</span><p>${focus.quest||'There isn’t enough evidence for a specific adjustment. Let the next game add context.'}</p></div><button class="full-review" id="deeper">${deep?'Back to match focus':'Open the full review'} <span>${deep?'←':'↗'}</span></button></aside></div><section class="card moments"><h3>${deep?'Timestamped observations':'Worth a closer look'} <span style="color:var(--dim);font-size:12px;font-family:Inter"> / ${observations.length} observations</span></h3><div class="moment-grid">${observations.length?observations.map(o=>`<article class="moment"><time>${E.time(o.t)}</time><h4>${o.title}</h4><p>${o.body}</p></article>`).join(''):'<p class="chart-note">No supported moments crossed the observation thresholds in the available data.</p>'}</div></section>${deep?`<section class="card metrics"><h3>The numbers behind the review</h3><p class="chart-note">Medians exclude this match and use the same game mode within your 20-game window. Advice needs at least 5 other usable matches; this is an evidence rule, not statistical confidence. Lobby comparisons use 600-Soul bands; other metrics use 10%. Heroes can differ.</p><table><thead><tr><th>Metric</th><th>This game</th><th>Other-game median</th><th>Comparison</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.label}${teaching?`<p class="chart-note">${r.detail}</p>`:''}</td><td>${r.key==='earlyDeaths'&&E.valid(r.value)?`${num(r.value,1)} death${r.value===1?'':'s'}`:`${num(r.value,1)} ${r.unit}`}</td><td>${r.key==='earlyDeaths'&&E.valid(r.base)?`${num(r.base,1)} death${r.base===1?'':'s'}`:num(r.base,1)} <small>(${r.n} recent match${r.n===1?'':'es'})</small></td><td class="${r.descriptive?'':r.state==='above'?'up':r.state==='below'?'down':''}">${r.descriptive?(r.state==='unavailable'||r.state==='small sample'?r.state:r.delta>0?'higher · context only':r.delta<0?'lower · context only':'equal · context only'):r.state==='above'?'favorable':r.state==='below'?'less favorable':r.state}</td></tr>`).join('')}</tbody></table><p class="chart-note">Early-economy snapshot: ${E.valid(g.paceTime)?E.time(g.paceTime):'unavailable'}. Lobby snapshot: ${E.valid(g.lobbyTime)?E.time(g.lobbyTime):'unavailable'}. Team-damage snapshot: ${E.valid(g.damageTime)?E.time(g.damageTime):'unavailable'}. Early snapshots can be up to 90 seconds from the target; shorter matches are excluded from those metrics. Missing fields stay unavailable.${g.legacyTiming?" This cached game was extracted by the earlier version; its unverifiable cross-player lobby and damage metrics stay unavailable while new games replace the cache naturally.":""}</p></section>`:''}`;
 $('#deeper').onclick=()=>{deep=!deep;renderMatch();const target=deep?$('.metrics'):$('#workspace');target.tabIndex=-1;target.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:'instant'});};}
function status(s){$('#status').textContent=s;}
async function loadAccount(id){if(busy)return;const keep=account===id&&!demo?games[selected]?.id:null;busy=true;account=id;demo=false;selected=0;$('#rank-context')?.remove();E.storage.write('account',id);games=E.windowOf(E.storage.read('games:'+id,[])).map(E.migrate);selected=Math.max(0,games.findIndex(g=>String(g.id)===String(keep)));$('#identity').textContent='Steam account '+id;$('#mode').textContent='YOUR MATCHES';$('#sync').hidden=false;$('#sync').disabled=true;$('#connect').disabled=true;render();status('Checking for new matches…');
 try{const result=await E.sync(id,games,(n,total)=>status(`Preparing your window · ${n} of ${total}`));games=result.games;selected=Math.max(0,games.findIndex(g=>String(g.id)===String(keep)));identityDetails(id).catch(()=>{});const saved=E.storage.write('games:'+id,games);render();status(result.rateLimited?'The service is rate-limiting requests. Your window is kept; wait before refreshing.':result.failed?`${result.failed} matches have incomplete data. Refresh to retry.`:games.length?`${games.length} recent match${games.length===1?'':'es'} · ${saved?'saved on this device':'storage unavailable; available this session'}`:'No public matches were returned for this account.');}catch(e){status(e.message+(games.length?' Showing your saved window.':''));}finally{busy=false;$('#sync').disabled=false;$('#connect').disabled=false;}
}
$('#strip').onclick=e=>{const b=e.target.closest('[data-select]');if(b){selected=Number(b.dataset.select);render();document.querySelector(`[data-select="${selected}"]`)?.focus({preventScroll:true});}};$('#overview').onclick=()=>{deep=false;renderMatch();};$('#review').onclick=()=>{deep=true;renderMatch();};$('#teaching').onchange=e=>{teaching=e.target.checked;E.storage.write('teaching',teaching);renderMatch();};$('#connect').onclick=()=>{$('#form-error').textContent='';$('#account').value=account||'';$('#account-dialog').showModal();};$('#close').onclick=()=>$('#account-dialog').close();$('#sync').onclick=()=>loadAccount(account);$('#account-form').onsubmit=e=>{e.preventDefault();try{const id=E.accountId($('#account').value);$('#form-error').textContent='';$('#account-dialog').close();loadAccount(id);}catch(err){$('#form-error').textContent=err.message;}};
$('#demo').onclick=()=>{account=null;E.storage.write('account',null);$('#rank-context')?.remove();demo=true;games=sample();selected=0;$('#identity').textContent='Example player';$('#mode').textContent='DEMO DATA';$('#sync').hidden=true;status('Illustrative matches · connect your account for a real review.');$('#account-dialog').close();render();};
async function cachedAsset(key,path){const c=E.storage.read(key);if(c&&Date.now()-c.at<604800000)return c.data;const data=await E.fetchJSON(path);E.storage.write(key,{at:Date.now(),data});return data;}
async function identityDetails(id){const results=await Promise.allSettled([E.fetchJSON(`/v1/players/steam?account_ids=${id}`),E.fetchJSON(`/v1/players/${id}/mmr-history`),cachedAsset('ranks','/v1/assets/ranks')]);if(account!==id||demo)return;const people=results[0].status==='fulfilled'?results[0].value:[],person=Array.isArray(people)?people.find(p=>String(p.account_id)===id):null;if(person)$('#identity').textContent=person.personaname||'Steam account '+id;const previous=$('#rank-context');if(previous)previous.remove();const block=document.createElement('div');block.id='rank-context';block.className='rank-context';const history=results[1].status==='fulfilled'&&Array.isArray(results[1].value)?results[1].value.filter(r=>games.some(g=>String(g.id)===String(r.match_id))).sort((a,b)=>a.start_time-b.start_time).slice(-20):[],rank=history.at(-1),catalog=results[2].status==='fulfilled'?results[2].value:[],tier=Array.isArray(catalog)?catalog.find(r=>r.tier===rank?.division):null;
 if(rank&&tier){block.innerHTML=`${tier.images?.small?`<img src="${esc(tier.images.small)}" alt="" width="32" height="32">`:''}<span>${esc(tier.name)} ${rank.division_tier} · ≈${num(rank.player_score,1)} score</span>`;const scores=history.map(r=>r.player_score).filter(E.valid);if(scores.length>1){const low=Math.min(...scores)-1,span=Math.max(4,Math.max(...scores)-low+1),points=scores.map((v,i)=>`${i/(scores.length-1)*90},${26-(v-low)/span*24}`).join(' ');block.innerHTML+=`<svg width="92" height="30" viewBox="0 0 92 30" role="img" aria-label="Rank score trend across available games in your window"><polyline points="${points}" fill="none" stroke="#e8b65e" stroke-width="2"/></svg>`;}}else block.textContent='Rank unavailable for this window';$('.identity').appendChild(block);}
async function init(){try{const r=await fetch('heroes.json');heroes=await r.json();}catch{}games=sample();render();if(account)loadAccount(account);cachedAsset('heroes','/v1/assets/heroes?only_active=true').then(list=>{if(Array.isArray(list)){heroes=Object.fromEntries(list.map(h=>[h.id,{name:h.name,icon:h.images?.icon_image_small}]));render();}}).catch(()=>{});}
