if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'select_match_review',title:'Select match review',description:'Select a match from the current 20-game window and display its detailed review.',inputSchema:{type:'object',properties:{matchNumber:{type:'integer',minimum:1,maximum:20}},required:['matchNumber'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!Number.isInteger(input?.matchNumber)||input.matchNumber<1||input.matchNumber>games.length)throw Error('Choose a match number in the current window.');selected=input.matchNumber-1;deep=true;render();return{matchNumber:selected+1,matchId:games[selected].id,demo,view:'deep-review'};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

